151	+/* ============================ Lái xe máy: chuyển động xe tay ga có nghiêng ============================
152	+   Spec D-040 §5.3 (+ §17.8, §17.9). Giữ khung của drStep (explore/drive/motion.ts): bước con ≤ CONFIG.drive.sim.dt (tối đa sim.steps, phần dư bỏ),
153	+   dời thân bằng drMove, mất phần tốc độ hướng vào vật cản một lần mỗi lần chạm, cọ thì hãm thêm perf.scrape; kết quả không phụ thuộc tần số khung.
154	+   Khác ô tô: người chơi điều khiển độ nghiêng, không phải góc lái.
155	+   - Ga / phanh: throttle, brakeK là lọc bậc một (chính xác theo hàm mũ) của đầu vào; gia tốc dùng trung bình đầu / cuối bước (bậc hai theo h).
156	+     Đường cong tăng tốc khớp như drAccel: a0 = 50 km/h / t50 tới 50 km/h, sau đó a0 · v50 / v · (1 − u^k), k giải sao cho 0 → 80 km/h đúng t80.
157	+     Phanh / phanh gấp nội suy khô ↔ ướt theo grip. Nhả ga hãm coast. Không có số lùi: đứng yên giữ phanh (không ga) thì dắt lùi ≤ walkBack.
158	+   - Tốc độ ≥ vBlend: độ nghiêng đích steer · bkLeanMax(v, grip); lean theo lò xo giảm chấn tới hạn, giải đúng dạng đóng mỗi bước
159	+     (ổn định với mọi h, kể cả 0,1 s); tần số nội suy leanHz → leanHzFast theo v / vMax (nặng tay khi nhanh); độ cong quỹ đạo g · tan(lean) / v².
160	+   - Dưới vBlend: trộn tuyến tính theo v / vBlend với lái động học kiểu xe đạp (góc lái steer tiến về đích theo steerRate, trả theo steerReturn,
161	+     bán kính trục sau nhỏ nhất turnRadius); độ nghiêng đích phần động học atan(v²κ / g). Độ cong từ độ nghiêng kẹp ≤ 1 / turnRadius nên đứng yên
162	+     mà còn nghiêng cũng không xoay tại chỗ. bkLeanMax kẹp tan(lean) ≤ v² / (g · turnRadius): bán kính rẽ không nhỏ hơn bán kính hình học.
163	+   - Giảm xóc trước / sau (chỉ hình + camera): lò xo giảm chấn, Euler ẩn; đích theo gia tốc dọc (phanh chúi đầu, ga nhún đuôi) + nhiễu mặt đường
164	+     rng(sus.seed) theo tốc độ; độ dốc đổi (mối nối ô) hích vận tốc. Vòng tua theo bkRpm, trễ tauUp / tauDown.
165	+   - Xi nhan tự tắt khi đã rẽ quá cancelYaw theo hướng xi nhan rồi trả thẳng, hoặc đi thẳng quá cancelS. stuck: s bị chặn mà vẫn vặn ga.
166	+   - Thân va chạm: người gọi đặt drUseBody(BK_BODY) trước; bkStep không đổi thân. Sơ tán nhịp quay Cầu sông Hàn: drEvacStep rồi lean = 0.
167	+   Quy ước hướng như ô tô: yaw = 0 mũi +X, vectơ tiến (cos yaw, −sin yaw); steer > 0 / lean > 0 = rẽ / nghiêng trái.
168	+   Không cấp phát mỗi khung (D-018). Không import three. */
169	+import { CONFIG } from '../../config';
170	+import { rng } from '../../common/math';
171	+import { drGround, type DrNet } from '../drive/net';
172	+import { drMove, type DrBody, type DrPose, type DrBox } from '../drive/collide';
173	+import { drCreate, drEvacStep, type DrState } from '../drive/motion';
174	+
175	+export interface BkInput { gas: number; brake: number; steer: number; hard: boolean; grip: number }   // gas, brake 0..1; steer −1..1 (trái +); hard: phanh gấp; grip 0 (ướt hẳn)..1 (khô)
176	+export interface BkState extends DrState { lean: number; leanV: number; susF: number; susFV: number; susR: number; susRV: number; rpm: number; throttle: number; brakeK: number; acc: number; sig: -1 | 0 | 1; sigYaw: number; sigT: number; stuck: number }   // lean: rad (trái +), leanV: rad/s; susF / susR: m lún giảm xóc (+ = nén), susFV / susRV: m/s; rpm: vòng/phút; throttle, brakeK: 0..1 đã làm mượt; acc: m/s² gia tốc dọc; sig: xi nhan −1 phải / 0 / 1 trái; sigYaw: rad đã rẽ theo hướng xi nhan; sigT: s đi thẳng kể từ lúc bật / lần rẽ cuối; stuck: s bị chặn mà vẫn vặn ga
177	+
178	+const B = CONFIG.bike.body, P = CONFIG.bike.perf, CVT = CONFIG.bike.cvt, SUS = CONFIG.bike.sus, SG = CONFIG.bike.signal, SIM = CONFIG.drive.sim;
179	+const L = B.wheelbase, G = P.latG;
180	+export const BK_BODY: DrBody = { hl: B.length / 2, hw: B.width / 2, ax: B.wheelbase / 2, height: B.height };
181	+const V50 = 50 / 3.6, V80 = 80 / 3.6;                                // m/s — mốc t50, t80
182	+const STEER_MAX = Math.atan(L / P.turnRadius);                       // rad — góc lái lớn nhất: bán kính trục sau = turnRadius
183	+const KAPPA_MAX = 1 / P.turnRadius;                                  // 1/m — độ cong lớn nhất
184	+const SUS_W = 2 * Math.PI * SUS.hz;
185	+const NOISE = rng(SUS.seed);                                         // nhiễu mặt đường, chuỗi riêng (không dùng rand())
186	+
187	+/* ===== Đường cong tăng tốc ===== */
188	+let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
189	+function bkAccelK(v: number, k: number): number {
190	+  if (v <= V50) return A0;
191	+  if (v >= P.vMax) return 0;
192	+  const u = (v - V50) / (P.vMax - V50);
193	+  return A0 * V50 / v * (1 - Math.pow(u, k));
194	+}
195	+/* Thời gian 0 → 80 km/h với số mũ k (tích phân dv / a, điểm giữa) */
196	+function bkT80(k: number): number {
197	+  const N = 2000, h = (V80 - V50) / N;
198	+  let t = V50 / A0;
199	+  for (let i = 0; i < N; i++) t += h / bkAccelK(V50 + (i + 0.5) * h, k);
200	+  return t;
201	+}
202	+function bkFitAccel(): void {
203	+  A0 = V50 / P.t50;
204	+  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: bkT80 giảm theo k
205	+  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (bkT80(m) > P.t80) lo = m; else hi = m; }
206	+  KEXP = (lo + hi) / 2;
207	+}
208	+/* m/s² khi vặn hết ga ở tốc độ v ≥ 0 */
209	+export function bkAccel(v: number): number {
210	+  if (Number.isNaN(KEXP)) bkFitAccel();
211	+  return bkAccelK(v, KEXP);
212	+}
213	+
214	+/* rad — độ nghiêng lớn nhất ở tốc độ v với độ bám grip: khô ↔ ướt, kẹp để bán kính rẽ không nhỏ hơn turnRadius */
215	+export function bkLeanMax(v: number, grip: number): number {
216	+  const g = grip > 1 ? 1 : grip < 0 ? 0 : grip, m = P.leanMaxWet + (P.leanMax - P.leanMaxWet) * g;
217	+  const geom = Math.atan(v * v / (G * P.turnRadius));
218	+  return geom < m ? geom : m;
219	+}
220	+
221	+/* vòng/phút — vòng tua đích của hộp số vô cấp ở tốc độ v (m/s, dấu bỏ qua) và tay ga throttle (0..1).
222	+   Nhả ga: theo tỉ số truyền (idle → engage tới engageV, rồi engage → max tới vMax). Vặn ga: ly tâm trượt ở engage lúc đứng,
223	+   tua lên vùng công suất power khi xe nhích tới engageV, rồi giữ power cho tới khi đường tỉ số vượt lên. */
224	+export function bkRpm(v: number, throttle: number): number {
225	+  const a = Math.abs(v), t = throttle > 1 ? 1 : throttle < 0 ? 0 : throttle;
