+  bkSignal(s, 1); assert.equal(s.sig, 1);
+  bkSignal(s, 1); assert.equal(s.sig, 0, 'bấm lại cùng hướng: tắt');
+  const t = state(-150, 0, 0, 8), lnet = longNet();
